const OrgSiteSleWanResponseSchema = z
  .object({
    end: z.number(),
    interval: z.int(),
    limit: z.int(),
    page: z.int(),
    results: z
      .array(
        z
          .object({
            'application-health': z.number().exactOptional(),
            'gateway-health': z.number().exactOptional(),
            num_clients: z.number().exactOptional(),
            num_gateways: z.number().exactOptional(),
            site_id: z.uuid().min(1),
            'wan-link-health': z.number().exactOptional(),
          })
          .openapi({ required: ['site_id'] }),
      )
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      }),
    start: z.number(),
    total: z.int(),
  })
  .openapi({
    description: '',
    required: ['start', 'end', 'interval', 'limit', 'page', 'total', 'results'],
    'x-examples': {
      'example-1': {
        end: 1651323600,
        interval: 3600,
        limit: 1,
        page: 2,
        results: [
          {
            'application-health': 0.8250000047942866,
            'gateway-health': 1,
            num_clients: 65,
            num_gateways: 1,
            site_id: 'f5fcbee5-1234-5678-9101-1619ede87879',
            'wan-link-health': 0.9988471089272484,
          },
        ],
        start: 1651269600,
        total: 4,
      },
    },
  })
  .openapi('OrgSiteSleWanResponse')

