const ApitokenSchema = z
  .object({
    created_by: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'for Org token only. email of the token creator / null if creator is deleted',
      }),
    created_time: z.int().exactOptional().openapi({ readOnly: true }),
    id: z.uuid().exactOptional().openapi({ readOnly: true }),
    key: z.string().exactOptional().openapi({ readOnly: true }),
    last_used: z.int().nullable().exactOptional().openapi({ readOnly: true }),
    name: z.string().exactOptional().openapi({ description: 'name of the token' }),
    org_id: z.uuid().exactOptional().openapi({ readOnly: true }),
    privileges: z
      .array(PrivilegesSchema)
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ description: 'list of privileges the token has on the orgs/sites' }),
  })
  .openapi({
    description: 'API Token',
    'x-examples': {
      'example-1': {
        id: '864f351a-1377-4ad9-83f8-72f3fe6199ba',
        key: '1qkb...QQCL',
        name: 'org_token_xyz',
        org_id: 'bc411cd9-0d1b-4713-94df-eee8617758ed',
      },
    },
    required: [],
  })
  .openapi('Apitoken')

const AptemplateSchema = z
  .object({
    ap_matching: z
      .object({
        enabled: z.boolean().exactOptional(),
        rules: z
          .array(
            z
              .object({
                match_model: z.string().min(1).exactOptional(),
                name: z.string().min(1).exactOptional(),
                port_config: z
                  .record(z.string(), ApPortConfigSchema)
                  .exactOptional()
                  .openapi({
                    description: 'The property key is the interface(s) name (e.g. "eth1,eth2")',
                  }),
              })
              .openapi({ required: [] }),
          )
          .min(1)
          .superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          })
          .exactOptional(),
      })
      .openapi({ required: [] }),
    created_time: z.number().exactOptional().openapi({ readOnly: true }),
    for_site: z.boolean().exactOptional().openapi({ readOnly: true }),
    id: z.uuid().exactOptional().openapi({ readOnly: true }),
    modified_time: z.number().exactOptional().openapi({ readOnly: true }),
    org_id: z.uuid().exactOptional().openapi({ readOnly: true }),
    site_id: z.uuid().exactOptional().openapi({ readOnly: true }),
    wifi: z
      .object({
        cisco_enabled: z.boolean().exactOptional(),
        disable_11k: z.boolean().default(false).exactOptional(),
        disable_radios_when_power_constrained: z.boolean().exactOptional(),
        enable_arp_spoof: z.boolean().exactOptional(),
        enable_shared_radio_scanning: z.boolean().default(false).exactOptional(),
        enabled: z.boolean().default(true).exactOptional(),
        locate_connected: z.boolean().default(false).exactOptional(),
        locate_unconnected: z.boolean().default(false).exactOptional(),
        mesh_allow_dfs: z.boolean().default(false).exactOptional(),
        mesh_enable_crm: z.boolean().exactOptional(),
        mesh_enabled: z.boolean().exactOptional(),
        proxy_arp: z.boolean().default(false).exactOptional(),
      })
      .exactOptional()
      .openapi({ required: [] }),
  })
  .openapi({ description: '', required: ['ap_matching'], 'x-examples': {} })
  .openapi('Aptemplate')

