        guest_network: 'string',
        mac_limit: 0,
        mode: 'access',
        mtu: 0,
        networks: ['string'],
        poe_disabled: true,
        port_auth: 'string',
        port_network: 'string',
        speed: 'string',
        storm_control: {},
