const DeviceUpgradeSchema = z
  .object({
    canary_phases: z
      .array(z.int())
      .default([1, 10, 50, 100])
      .exactOptional()
      .openapi({
        description:
          'phases for canary deployment. Each phase represents percentage of AP’s that need to be upgraded. default is [1, 10, 50, 100]',
      }),
    device_ids: z.array(z.string()).exactOptional(),
    enable_p2p: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'whether to allow local AP-to-AP FW upgrade' }),
    force: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description: 'true will force upgrade when requested version is same as running version',
      }),
    max_failure_percentage: z
      .number()
      .min(0)
      .max(100)
      .default(5)
      .exactOptional()
      .openapi({
        description:
          'percentage of failures allowed across the entire upgrade(not applicable for `big_bang`)',
      }),
    max_failures: z
      .array(z.int())
      .exactOptional()
      .openapi({
        description:
          'number of failures allowed within each phase(applicable for `canary` or `rrm`). Will be used if provided, else max_failure_percentage will be used',
      }),
    models: z.array(z.string()).exactOptional(),
    p2p_cluster_size: z.int().min(0).default(10).exactOptional().openapi({ example: 0 }),
    p2p_parallelism: z
      .int()
      .exactOptional()
      .openapi({ description: 'number of parallel p2p download batches to creat' }),
    reboot: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Reboot device immediately after upgrade is completed (Available on Junos OS devices)',
      }),
    reboot_at: z
      .number()
      .exactOptional()
      .openapi({
        description: 'reboot start time in epoch seconds, default is `start_time`',
        example: 1624399840,
      }),
    rrm_first_batch_percentage: z
      .int()
      .exactOptional()
      .openapi({
        description: 'percentage of AP’s that need to be present in the first rrm batch',
        example: 2,
      }),
    rrm_max_batch_percentage: z
      .int()
      .exactOptional()
      .openapi({
        description: 'max percentage of AP’s that need to be present in each rrm batch',
        example: 10,
      }),
    rrm_mesh_upgrade: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'sequential or parallel (default parallel). Whether to upgrade mesh AP’s parallelly or sequentially at the end of the upgrade',
      }),
    rrm_node_order: z
      .enum(['fringe_to_center', 'center_to_fringe'])
      .default('fringe_to_center')
      .exactOptional()
      .openapi({
        description: 'Used in rrm to determine whether to start upgrade from fringe or center AP’s',
      }),
    rrm_slow_ramp: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'true will make rrm batch sizes slowly ramp up' }),
    snapshot: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Perform recovery snapshot after device is rebooted (Available on Junos OS devices)',
      }),
    start_time: z
      .number()
      .exactOptional()
      .openapi({
        description: 'upgrade start time in epoch seconds, default is now',
        example: 1624399840,
      }),
    strategy: z
      .enum(['big_bang', 'canary', 'serial', 'rrm'])
      .default('big_bang')
      .exactOptional()
      .openapi({
        description:
          '`big_bang` (upgrade all at once), `serial` (one at a time), `canary` or `rrm`',
      }),
    version: z.string().min(1).default('stable').exactOptional().openapi({ example: '3.1.5' }),
  })
  .openapi({
    description: '',
    title: 'device_upgrade',
    'x-examples': {
      'example-1': {
        canary_phases: [1, 10, 50, 100],
        device_ids: ['string'],
        enable_p2p: true,
        force: false,
        max_failure_percentage: 5,
        max_failures: [0],
        models: ['string'],
        p2p_cluster_size: 10,
        reboot: false,
        reboot_at: 1624399840,
        rrm_first_batch_percentage: 2,
        rrm_max_batch_percentage: 10,
        rrm_mesh_upgrade: 'string',
        rrm_node_order: 'fringe_to_center',
        rrm_slow_ramp: true,
        snapshot: false,
        start_time: 1624399840,
        strategy: 'big_bang',
        version: 'stable',
      },
    },
    required: [],
  })
  .openapi('DeviceUpgrade')

const DeviceUpgradeResponseSchema = z
  .object({
    counts: z
      .object({
        download_requested: z
          .int()
          .exactOptional()
          .openapi({
            description: 'count of devices which cloud has requested to download firmware',
          }),
        downloaded: z
          .int()
          .exactOptional()
          .openapi({ description: 'count of ap’s which have the firmware downloaded' }),
        failed: z
          .int()
          .exactOptional()
          .openapi({ description: 'count of devices which have failed to upgrade' }),
        reboot_in_progress: z
          .int()
          .exactOptional()
          .openapi({ description: 'count of devices which are rebooting' }),
        rebooted: z
          .int()
          .exactOptional()
          .openapi({ description: 'count of devices which have rebooted successfully' }),
        scheduled: z
          .int()
          .exactOptional()
          .openapi({ description: 'count of devices which cloud has scheduled an upgrade for' }),
        skipped: z
          .int()
          .exactOptional()
          .openapi({
            description:
              'count of devices which skipped upgrade since requested version was same as running version. Use force to always upgrade',
          }),
        total: z
          .int()
          .exactOptional()
          .openapi({ description: 'count of devices part of this upgrade' }),
        upgraded: z
          .int()
          .exactOptional()
          .openapi({ description: 'count of devices which have upgraded successfully' }),
      })
      .exactOptional()
      .openapi({ readOnly: true, required: [] }),
    current_phase: z
      .int()
      .exactOptional()
      .openapi({ description: 'current canary or rrm phase in progress' }),
    enable_p2p: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'whether to allow local AP-to-AP FW upgrade' }),
    force: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'whether to force upgrade when requested version is same as running version',
      }),
    id: z.uuid().min(1).openapi({ description: 'unique id for the upgrade', readOnly: true }),
    max_failure_percentage: z
      .int()
      .exactOptional()
      .openapi({ description: 'percentage of failures allowed' }),
    max_failures: z
      .array(z.int())
      .exactOptional()
      .openapi({
        description: 'number of failures allowed within a canary phase or serial rollout',
      }),
    reboot_at: z.int().exactOptional().openapi({ description: 'reboot start time in epoch' }),
    start_time: z
      .number()
      .exactOptional()
      .openapi({ description: 'firmware download start time in epoch' }),
    status: z
      .enum(['created', 'completed', 'canceled', 'downloading'])
      .exactOptional()
      .openapi({ description: 'status upgrade is in' }),
    strategy: z
      .literal('big_bang')
      .default('big_bang')
      .exactOptional()
      .openapi({ description: 'upgrade strategy' }),
    target_version: z
      .string()
      .min(1)
      .exactOptional()
      .openapi({ description: 'version to upgrade to' }),
    upgrade_plan: z
      .object({})
      .exactOptional()
      .openapi({ description: 'a dictionary of rrm phase number to devices part of that phase' }),
  })
  .openapi({
    description: '',
    required: ['id'],
    title: 'device_upgrade_response',
    'x-examples': {
      'example-1': {
        counts: {
          download_requested: 0,
          downloaded: 0,
          failed: 0,
          reboot_in_progress: 0,
          rebooted: 0,
          skipped: 0,
          total: 0,
        },
        enable_p2p: true,
        force: true,
        id: '449f6eca-6276-4997-bfeb-53cbbbba6f08',
        start_time: 0,
        status: 'created',
        strategy: 'big_bang',
        target_version: 'string',
      },
    },
  })
  .openapi('DeviceUpgradeResponse')

