const GatewaytemplateSchema = z
  .object({
    additional_config_cmds: z.array(z.string()).exactOptional(),
    bgp_config: z.record(z.string(), JunosBgpConfigSchema).exactOptional(),
    created_time: z.number().exactOptional().openapi({ readOnly: true }),
    dhcpd_config: z
      .record(
        z.string(),
        z
          .object({
            dns_servers: z.array(z.ipv4()).exactOptional(),
            dns_suffix: z.array(z.string()).exactOptional(),
            fixed_bindings: z
              .record(
                z.string(),
                z
                  .object({ ip: z.ipv4(), name: z.string().exactOptional() })
                  .openapi({ required: ['ip'] }),
              )
              .exactOptional()
              .openapi({ description: 'The property key is the device MAC address' }),
            gateway: z.ipv4().exactOptional(),
            ip_end: z.ipv4().exactOptional(),
            ip_start: z.ipv4().exactOptional(),
            servers: z.array(z.ipv4()).exactOptional(),
            type: z.enum(['local', 'relay']).default('local').exactOptional(),
          })
          .openapi({ required: [] }),
      )
      .exactOptional()
      .openapi({ description: 'The property key is the network name' }),
    extra_routes: z
      .record(
        z.string(),
        z
          .object({ via: z.ipv4().exactOptional() })
          .openapi({
            description: 'The property key is a CIDR or name from `networks`',
            required: [],
          }),
      )
      .exactOptional(),
    gateway_matching: TemplateGatewayMatchingSchema.exactOptional(),
    id: z.uuid().exactOptional().openapi({ readOnly: true }),
    ip_configs: z
      .record(
        z.string(),
        z
          .object({
            ip: z.ipv4().exactOptional(),
            netmask: z.string().exactOptional().openapi({ example: '/24' }),
          })
          .openapi({ required: [] }),
      )
      .exactOptional()
      .openapi({ description: 'The property key is the network name' }),
    modified_time: z.number().exactOptional().openapi({ readOnly: true }),
    name: z.string(),
    networks: z
      .record(z.string(), NetworkSchema)
      .exactOptional()
      .openapi({ description: 'The property key is the network name' }),
    oob_ip_config: JunosOobIpConfigSchema.exactOptional(),
    org_id: z.uuid().exactOptional().openapi({ readOnly: true }),
    path_preferences: z
      .record(
        z.string(),
        z
          .object({
            paths: z
              .object({
                cost: z.int().exactOptional(),
                gateway_ip: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'if `type`==`local`, if a different gateway is desired',
                  }),
                internet_access: z
                  .boolean()
                  .default(false)
                  .exactOptional()
                  .openapi({
                    description: 'when `type`==`vpn`, if this vpn path can be used for internet',
                  }),
                name: z.string().exactOptional(),
                networks: z
                  .array(z.string())
                  .exactOptional()
                  .openapi({ description: 'if `type`==`local`' }),
                target_ips: z
                  .array(z.string())
                  .exactOptional()
                  .openapi({
                    description: 'if `type`==`local`, if destination IP is to be replaced',
                  }),
                type: z.enum(['local', 'wan', 'vpn', 'tunnel']).exactOptional(),
              })
              .exactOptional()
              .openapi({ required: [] }),
            strategy: z.enum(['ordered', 'weighted', 'ecmp']).default('ordered').exactOptional(),
          })
          .openapi({ description: 'The property key is the path name', required: [] }),
      )
      .exactOptional()
      .openapi({ description: 'experimental' }),
    port_config: z
      .record(z.string(), JunosPortConfigGatewaySchema)
      .exactOptional()
      .openapi({
        description: 'The property key is the port(s) name or range (e.g. "ge-0/0/0-10")',
      }),
    routing_policies: z
      .record(z.string(), JunosRoutingPolicySchema)
      .exactOptional()
      .openapi({ description: 'The property key is the routing policy name' }),
    service_policies: z
      .array(
        z
          .object({
            action: z.enum(['allow', 'deny']).default('allow').exactOptional(),
            ewf: z
              .array(
                z
                  .object({
                    alert_only: z.boolean().exactOptional(),
                    block_message: z
                      .string()
                      .exactOptional()
                      .openapi({ example: 'Access to this URL Category has been blocked' }),
                    enabled: z.boolean().default(false).exactOptional(),
                    profille: z.enum(['strict', 'standard']).default('strict').exactOptional(),
                  })
                  .openapi({ required: [] }),
              )
              .exactOptional(),
            idp: JunosIdpConfigSchema.exactOptional(),
            local_routing: z
              .boolean()
              .default(false)
              .exactOptional()
              .openapi({ description: 'access within the same VRF' }),
            name: z.string().exactOptional(),
            path_preferences: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'by default, we derive all paths available and use them\noptionally, you can customize by using `path_preference`',
              }),
            servicepolicy_id: z
              .uuid()
              .exactOptional()
              .openapi({
                description:
                  'used to link servicepolicy defined at org level and overwrite some attributes',
              }),
            services: z.array(z.string()).exactOptional(),
            tenants: z.array(z.string()).exactOptional(),
          })
          .openapi({ required: [] }),
      )
      .exactOptional(),
    tunnel_configs: z
      .record(z.string(), GatewaytemplateTunnelConfigsSchema)
      .exactOptional()
      .openapi({ description: 'Property key is the tunnel name' }),
    type: z.enum(['standalone', 'spoke', 'hub']).default('standalone').exactOptional(),
  })
