const OrgDeviceUpgradeResponseSchema = z
  .object({
    enable_p2p: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'whether to allow local AP-to-AP FW upgrade' }),
    force: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'whether to force upgrade when requested version is same as running version',
      }),
    id: z.uuid().min(1).openapi({ description: 'unique id for the upgrade', readOnly: true }),
    start_time: z.number().exactOptional().openapi({ description: 'upgrade start time in epoch' }),
    status: z
      .enum(['created', 'in_progress', 'completed', 'canceled'])
      .exactOptional()
      .openapi({ description: 'status upgrade is in' }),
    strategy: z
      .literal('big_bang')
      .default('big_bang')
      .exactOptional()
      .openapi({ description: 'upgrade strategy' }),
    target_version: z
      .string()
      .min(1)
      .exactOptional()
      .openapi({ description: 'version to upgrade to' }),
    upgrades: z
      .array(
        z
          .object({
            site_id: z.uuid().exactOptional(),
            upgrade: z
              .object({
                id: z.uuid().exactOptional(),
                start_time: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'upgrade start time in epoch' }),
                status: z
                  .enum(['created', 'in_progress', 'completed', 'cancelled'])
                  .exactOptional()
                  .openapi({ description: 'status upgrade is in' }),
                targets: z
                  .object({
                    downloaded: z
                      .array(z.uuid())
                      .exactOptional()
                      .openapi({ description: 'devices which have the firmware downloaded' }),
                    failed: z
                      .array(z.uuid())
                      .exactOptional()
                      .openapi({ description: 'devices which have the failed to upgrade' }),
                    reboot_in_progress: z
                      .array(z.uuid())
                      .exactOptional()
                      .openapi({ description: 'devices which are rebooting' }),
                    rebooted: z
                      .array(z.uuid())
                      .exactOptional()
                      .openapi({ description: 'devices which have rebooted successfully' }),
                    scheduled: z
                      .array(z.uuid())
                      .exactOptional()
                      .openapi({ description: 'devices which cloud has scheduled an upgrade' }),
                    skipped: z
                      .array(z.uuid())
                      .exactOptional()
                      .openapi({
                        description:
                          'devices which have skipped upgrade since requested version was same as running version. Use `force` to always upgrade',
                      }),
                    upgraded: z
                      .array(z.uuid())
                      .exactOptional()
                      .openapi({ description: 'devices which have upgraded successfully' }),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
              })
              .exactOptional()
              .openapi({ required: [] }),
          })
          .openapi({ required: [] }),
      )
      .exactOptional(),
  })
