const RssizoneSchema = z
  .object({
    created_time: z.number().exactOptional().openapi({ readOnly: true }),
    devices: z
      .array(
        z
          .object({ device_id: z.uuid(), rssi: z.int().openapi({ description: 'RSSI threshold' }) })
          .openapi({ required: ['device_id', 'rssi'] }),
      )
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description: 'List of devices and the respective RSSI values to be considered in the zone',
      }),
    for_site: z.boolean().exactOptional().openapi({ readOnly: true }),
    id: z.uuid().exactOptional().openapi({ readOnly: true }),
    modified_time: z.number().exactOptional().openapi({ readOnly: true }),
    name: z.string().exactOptional().openapi({ description: 'The name of the zone' }),
    org_id: z.uuid().exactOptional().openapi({ readOnly: true }),
    site_id: z.uuid().exactOptional().openapi({ readOnly: true }),
  })
  .openapi({
    description: 'RSSI Zone',
    required: ['devices'],
    'x-examples': {
      'example-1': {
        devices: [{ device_id: '00000000-0000-0000-1000-5c5b35bd76bb', rssi: -80 }],
        name: 'Board Room',
      },
    },
  })
  .openapi('Rssizone')

