const SleSummarySchema = z
  .object({
    classifiers: z
      .array(
        z
          .object({
            impact: z
              .object({
                num_aps: z.number(),
                num_users: z.number(),
                total_aps: z.number(),
                total_users: z.number(),
              })
              .exactOptional()
              .openapi({ required: ['num_users', 'num_aps', 'total_users', 'total_aps'] }),
            interval: z.number(),
            name: z.string().min(1),
            samples: z
              .object({
                degraded: z.array(z.number()),
                duration: z.array(z.number()),
                total: z.array(z.number()),
              })
              .exactOptional()
              .openapi({ required: ['duration', 'total', 'degraded'] }),
            x_label: z.string().min(1),
            y_label: z.string().min(1),
          })
          .openapi({ required: ['name', 'x_label', 'y_label', 'interval'] }),
      )
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      }),
    end: z.number(),
    events: z.array(z.object({})),
    impact: z
      .object({
        num_aps: z.number(),
        num_users: z.number(),
        total_aps: z.number(),
        total_users: z.number(),
      })
      .openapi({ required: ['num_users', 'num_aps', 'total_users', 'total_aps'] }),
    sle: z
      .object({
        interval: z.number(),
        name: z.string().min(1),
        samples: z
          .object({
            degraded: z.array(z.number()),
            total: z.array(z.number()),
            value: z.array(z.number()),
          })
          .openapi({ required: ['total', 'degraded', 'value'] }),
        x_label: z.string().min(1),
        y_label: z.string().min(1),
      })
      .openapi({ required: ['name', 'x_label', 'y_label', 'interval', 'samples'] }),
    start: z.number(),
  })
