const StatsSdkclientDetailsSchema = z
  .object({
    id: z.uuid(),
    last_seen: z.number().openapi({ description: 'last seen timestamp' }),
    map_id: z
      .uuid()
      .nullable()
      .exactOptional()
      .openapi({ description: 'map_id of the sdk client (if known), or null' }),
    name: z
      .string()
      .exactOptional()
      .openapi({ description: 'name of the sdk client (if provided)' }),
    network_connection: z
      .object({ mac: z.string(), rssi: z.number(), signal_level: z.number(), type: z.string() })
      .exactOptional()
      .openapi({
        description:
          'various network connection info for the SDK client (if known, else omitted), with RSSI in dBm, and signal level as',
        required: ['type', 'rssi', 'mac', 'signal_level'],
      }),
    uuid: z.uuid().openapi({ description: 'uuid of the sdk client' }),
    vbeacons: z
      .array(z.object({ id: z.uuid(), since: z.number() }).openapi({ required: ['id', 'since'] }))
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description: 'list of beacon_id’s of the sdk client is in and since when (if known)',
      }),
    x: z
      .number()
      .exactOptional()
      .openapi({ description: 'x (in pixels) of user location on the map (if known)' }),
    y: z
      .number()
      .exactOptional()
      .openapi({ description: 'y (in pixels) of user location on the map (if known)' }),
    zones: z
      .array(z.object({ id: z.uuid(), since: z.number() }).openapi({ required: ['id', 'since'] }))
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description: 'list of zone_id’s of the sdk client is in and since when (if known)',
      }),
  })
  .openapi({
    description: 'SDK Client Details statistics',
    required: ['id', 'uuid', 'last_seen'],
    'x-examples': {
      'example-1': {
        id: 'de87bf9d-183f-e383-cc68-6ba43947d403',
        last_seen: 1428939600,
        map_id: '845a23bf-bed9-e43c-4c86-6fa474be7ae5',
        name: "John's iPhone",
        network_connection: { mac: 'c3-b6-e5-af-41-15', rssi: -75, signal_level: 3, type: 'WiFi' },
        uuid: 'ada72f8f-1643-e5c6-94db-f2a5636f1a64',
        vbeacons: [{ id: 'd379d29d-24b4-96c5-5dd4-6f2a2dc5aaeb', since: 1428939300 }],
        x: 60,
        y: 80,
        zones: [{ id: '8ac84899-32db-6327-334c-9b6d58544cfe', since: 1428939600 }],
      },
    },
  })
  .openapi('StatsSdkclientDetails')

