const AnomalyMetricsResponse = {
  description: 'OK',
  content: {
    'application/json': {
      schema: z
        .object({
          end: z.int(),
          limit: z.int(),
          page: z.int(),
          results: z
            .array(AnomalySchema)
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
          start: z.int(),
        })
        .openapi({ required: ['start', 'end', 'limit', 'page', 'results'] }),
    },
  },
}

