const DeviceVersionResponse = {
  description: 'OK',
  content: {
    'application/json': {
      schema: z
        .array(
          z
            .object({
              model: z.string().openapi({ description: 'AP model (as seen in the device stats)' }),
              tag: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'annotation, stable / beta / alpha. Or it can be empty or nothing which is likely a dev build',
                }),
              version: z.string().openapi({ description: 'firmware version' }),
            })
            .openapi({ required: ['model', 'version'] }),
        )
        .min(1)
        .superRefine((items, ctx) => {
          const seen = new Map()
          for (const [i, val] of items.entries()) {
            const key = JSON.stringify(val)
            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
            else seen.set(key, i)
          }
        }),
      examples: {
        'example-1': {
          value: [
            { model: 'AP41', tag: 'stable', version: 'v0.1.543' },
            { model: 'AP21', version: 'v0.1.545' },
          ],
        },
      },
    },
  },
}

