const MxedgeUpdateInfoResponse = {
  description: 'OK',
  content: {
    'application/json': {
      schema: z
        .array(
          z
            .object({
              default: z.boolean().exactOptional(),
              package: z.string(),
              version: z.string(),
            })
            .openapi({ required: ['package', 'version'] }),
        )
        .min(1)
        .superRefine((items, ctx) => {
          const seen = new Map()
          for (const [i, val] of items.entries()) {
            const key = JSON.stringify(val)
            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
            else seen.set(key, i)
          }
        }),
      examples: {
        'example-1': {
          value: [
            { default: true, package: 'mxagent', version: '2.4.100' },
            { package: 'tunterm', version: '1.0.0' },
          ],
        },
      },
    },
  },
}

