const OrgDevicesResponse = {
  description: 'OK',
  content: {
    'application/json': {
      schema: z
        .object({
          results: z
            .array(
              z
                .object({ mac: z.string(), name: z.string() })
                .openapi({ required: ['mac', 'name'] }),
            )
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        })
        .openapi({ required: ['results'] }),
      examples: { 'example-1': { value: { results: [{ mac: 'string', name: 'string' }] } } },
    },
  },
}

