const SsoLatestFailuresResponse = {
  description: 'OK',
  content: {
    'application/json': {
      schema: z
        .object({
          results: z
            .array(
              z
                .object({
                  detail: z.string(),
                  saml_assertion_xml: z.string(),
                  timestamp: z.number(),
                })
                .openapi({ required: ['timestamp', 'detail', 'saml_assertion_xml'] }),
            )
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        })
        .openapi({ required: ['results'] }),
      examples: {
        'example-1': {
          value: { results: [{ detail: 'string', saml_assertion_xml: 'string', timestamp: 0 }] },
        },
      },
    },
  },
}

