export const postApiV1InstallerOrgsOrgIdDevicesRoute = createRoute({
  method: 'post',
  path: '/api/v1/installer/orgs/{org_id}/devices',
  tags: ['Installer'],
  summary: 'claimInstallerDevices',
  description: 'This mirrors `POST /api/v1/orgs/{org_id}/inventory` (see Inventory API)',
  operationId: 'claimInstallerDevices',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      description: 'Request Body',
      content: {
        'application/json': {
          schema: ModelArrayStringSchema,
          examples: { 'example-1': { value: ['6JG8E-PTFV2-A9Z2N', 'DVH4V-SNMSZ-PDXBR'] } },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              added: z.array(z.string()),
              duplicated: z.array(z.string()),
              error: z.array(z.string()),
              inventory_added: z
                .array(
                  z
                    .object({
                      mac: z.string(),
                      magic: z.string(),
                      model: z.string(),
                      serial: z.string(),
                      type: z.string(),
                    })
                    .openapi({ required: ['serial', 'model', 'type', 'magic', 'mac'] }),
                )
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
              inventory_duplicated: z
                .array(
                  z
                    .object({
                      mac: z.string(),
                      magic: z.string(),
                      model: z.string(),
                      serial: z.string(),
                      type: z.string(),
                    })
                    .openapi({ required: ['serial', 'model', 'type', 'magic', 'mac'] }),
                )
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
            })
            .openapi({
              required: ['added', 'duplicated', 'error', 'inventory_added', 'inventory_duplicated'],
            }),
          examples: {
            'example-1': {
              value: {
                added: ['6JG8E-PTFV2-A9Z2N'],
                duplicated: ['DVH4V-SNMSZ-PDXBR'],
                error: ['PO1025335ohoh'],
                inventory_added: [
                  {
                    mac: '5c5b35000018',
                    magic: '6JG8EPTFV2A9Z2N',
                    model: 'AP41',
                    serial: 'FXLH2015150025',
                    type: 'ap',
                  },
                ],
                inventory_duplicated: [
                  {
                    mac: '5c5b35000012',
                    magic: 'DVH4VSNMSZPDXBR',
                    model: 'AP41',
                    serial: 'FXLH2015150027',
                    type: 'ap',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: { description: 'Bad Request if none of the entries are valid' },
  },
})

export const putApiV1InstallerOrgsOrgIdDevicesDeviceMacRoute = createRoute({
  method: 'put',
  path: '/api/v1/installer/orgs/{org_id}/devices/{device_mac}',
  tags: ['Installer'],
  summary: 'provisionInstallerDevices',
  description:
    'Provision or Replace a device \n\nIf replacing_mac is in the request payload, other attributes are ignored, we attempt to replace existing device (with mac replacing_mac) with the inventory device being configured. The replacement device must be in the inventory but not assigned, and the replacing_mac device must be assigned to a site, and satisfy grace period requirements. The Device replaced will become unassigned.',
  operationId: 'provisionInstallerDevices',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema, device_mac: DeviceMacParamsSchema }),
    body: {
      description: 'Request Body',
      content: {
        'application/json': {
          schema: InstallerDevicesSchema,
          examples: {
            'example-1': {
              value: {
                deviceprofile_name: 'string',
                for_site: true,
                height: 0,
                map_id: '09d2b626-2e4e-45ef-a3c4-e6aeb6c83db1',
                name: 'string',
                orientation: 0,
                site_id: '72771e6a-6f5e-4de4-a5b9-1266c4197811',
                site_name: 'string',
                x: 0,
                y: 0,
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: OKResponse,
    400: {
      description: 'Bad Request',
      content: {
        'application/json': {
          schema: z.object({ detail: z.string() }).openapi({ required: ['detail'] }),
          examples: {
            'invalid mac given for replacing_mac': { value: { detail: 'invalid replacing_mac' } },
            'inventory device is already assigned': {
              value: { detail: 'device already assigned' },
            },
            outsite_of_grace_period: { value: { detail: 'outside of grace period' } },
            'replacing_mac device is not assigned to a site': {
              value: { detail: 'replacing_mac device is unassigned' },
            },
            'replacing_mac device last modified outside of grace period': {
              value: { detail: 'replacing_mac device outside of grace period' },
            },
          },
        },
      },
    },
    404: {
      description: 'Not Found',
      content: {
        'application/json': {
          schema: z
            .object({ detail: z.string().exactOptional() })
            .openapi({
              'x-examples': { 'example-1': { detail: 'replacing_mac inventory not found' } },
              required: [],
            }),
          examples: {
            'replacing_mac device is not in org inventory': {
              value: { detail: 'replacing_mac inventory not found' },
            },
            'replacing_mac device not found': {
              value: { detail: 'replacing_mac device not found' },
            },
          },
        },
      },
    },
  },
})

