export const postApiV1LoginRoute = createRoute({
  method: 'post',
  path: '/api/v1/login',
  tags: ['Login'],
  summary: 'login',
  description: 'Log in with email/password',
  operationId: 'login',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              email: z.string(),
              password: z.string(),
              two_factor: z.string().exactOptional(),
            })
            .openapi({ required: ['email', 'password'] }),
          examples: {
            'with 2FA': { value: { email: 'string', password: 'string', two_factor: 'string' } },
            'without 2FA': { value: { email: 'string', password: 'string' } },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Login Success',
      content: {
        'application/json': {
          schema: z
            .object({
              email: z.string().exactOptional(),
              two_factor_passed: z.boolean().exactOptional(),
              two_factor_required: z.boolean().exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            '2FA Required': {
              value: {
                email: 'test@mistsys.com',
                two_factor_passed: false,
                two_factor_required: true,
              },
            },
            OK: { value: {} },
          },
        },
      },
      headers: z.object({
        'Set-Cookie': {
          description: 'Session Cookie if login/password authentication is successful',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'Session Cookie if login/password authentication is successful',
              param: { required: false },
              example:
                'csrftoken=vwvBuq9qkqaKh7lu8tNc0gkvBfEaLAmx; expires=Tue, 15-Mar-2016 19:47:20 GMT; Max-Age=31449600; Path=/',
            }),
        },
      }),
    },
    400: {
      description: 'Login Failed',
      content: {
        'application/json': {
          schema: z.xor([
            z
              .object({ detail: z.string(), forward_url: z.string().exactOptional() })
              .openapi({ required: ['detail'] }),
          ]),
          examples: {
            'example-1': {
              value: {
                detail: 'sso admin login needs to be initiated by IdP',
                forward_url: 'https://my.sso/idp_sso_url',
              },
            },
          },
        },
      },
    },
  },
})

