export const postApiV1OrgsOrgIdApitokensRoute = createRoute({
  method: 'post',
  path: '/api/v1/orgs/{org_id}/apitokens',
  tags: ['Orgs API Tokens'],
  summary: 'createOrgApiToken',
  description:
    'Create Org API Token\nNote that the token key is only available during creation time.',
  operationId: 'createOrgApiToken',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z.string().min(1),
              privileges: z
                .array(
                  z
                    .object({
                      role: z.enum(['admin', 'write', 'read']),
                      scope: z.enum(['site', 'org', 'sitegroup']),
                      site_id: z.uuid().openapi({ description: 'if `scope`==`site`' }),
                      sitegroup_id: z
                        .uuid()
                        .exactOptional()
                        .openapi({ description: 'if `scope`==`sitegroup`' }),
                    })
                    .openapi({ required: ['scope', 'role', 'site_id'] }),
                )
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                })
                .openapi({ description: 'list of privileges the token has on the orgs/sites' }),
            })
            .openapi({
              description: '',
              required: ['name', 'privileges'],
              'x-examples': {
                'example-1': {
                  name: 'org_token_xyz',
                  privileges: [
                    { role: 'read', scope: 'org' },
                    {
                      role: 'admin',
                      scope: 'site',
                      site_id: 'd96e3952-53e8-4266-959a-45acd55f5114',
                    },
                    {
                      role: 'write',
                      scope: 'sitegroup',
                      sitegroup_id: '581328b6-e382-f54e-c9dc-999983183a34',
                    },
                  ],
                },
              },
            }),
        },
      },
    },
  },
  responses: { 200: ApitokenResponse },
})

