export const postApiV1OrgsOrgIdAssetsImportRoute = createRoute({
  method: 'post',
  path: '/api/v1/orgs/{org_id}/assets/import',
  tags: ['Orgs Assets'],
  summary: 'importOrgAssets',
  description:
    'Impert Org Assets. \n\nIt can be done via a CSV file or a JSON payload.\n\n#### CSV File Format\n```csv\nname,mac\n"asset_name",5c5b53010101\n``` ',
  operationId: 'importOrgAssets',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .object({ mac: z.string().min(1), name: z.string().min(1) })
                .openapi({ required: ['name', 'mac'] }),
            )
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            })
            .openapi({
              description: '',
              'x-examples': {
                'example-1': [
                  { mac: 'a31eb04e1c38', name: 'Expensive Instrument' },
                  { mac: 'a31eb04e1c37', name: 'Cheap Instrument' },
                ],
              },
            }),
          examples: {
            'example-1': {
              value: [
                { mac: 'a31eb04e1c38', name: 'Expensive Instrument' },
                { mac: 'a31eb04e1c37', name: 'Cheap Instrument' },
              ],
            },
          },
        },
        'multipart/form-data': {
          schema: z
            .object({
              file: z
                .file()
                .exactOptional()
                .openapi({ type: 'string', format: 'binary', description: 'CSV file' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: { 200: OKResponse },
})

