export const getApiV1OrgsOrgIdClientsEventsSearchRoute = createRoute({
  method: 'get',
  path: '/api/v1/orgs/{org_id}/clients/events/search',
  tags: ['Orgs Clients'],
  summary: 'searchOrgClientsEvents',
  description: 'Get Org Clients Events',
  operationId: 'searchOrgClientsEvents',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    query: z.object({
      type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'event type, e.g. MARVIS_EVENT_CLIENT_FBT_FAILURE',
            in: 'query',
            name: 'type',
            schema: { type: 'string' },
            required: false,
          },
        }),
      reason_code: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'for assoc/disassoc events',
            in: 'query',
            name: 'reason_code',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      ssid: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'SSID Name',
            in: 'query',
            name: 'ssid',
            schema: { type: 'string' },
            required: false,
          },
        }),
      ap: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'AP MAC',
            in: 'query',
            name: 'ap',
            schema: { type: 'string' },
            required: false,
          },
        }),
      proto: z
        .enum(['b', 'g', 'n', 'ac', 'ax', 'a'])
        .exactOptional()
        .openapi({
          param: {
            description: '802.11 standard',
            in: 'query',
            name: 'proto',
            schema: { enum: ['b', 'g', 'n', 'ac', 'ax', 'a'], type: 'string' },
            required: false,
          },
        }),
      band: z
        .enum(['24', '5'])
        .exactOptional()
        .openapi({
          param: {
            description: '24 / 5',
            in: 'query',
            name: 'band',
            schema: { enum: ['24', '5'], type: 'string' },
            required: false,
          },
        }),
      wlan_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'wlan_id',
            in: 'query',
            name: 'wlan_id',
            schema: { type: 'string' },
            required: false,
          },
        }),
      limit: LimitParamsSchema,
      start: StartParamsSchema,
      end: EndParamsSchema,
      duration: DurationParamsSchema,
    }),
  },
  responses: { 200: EventsSearchResponse },
})

