export const getApiV1OrgsOrgIdDevicesRadioMacsRoute = createRoute({
  method: 'get',
  path: '/api/v1/orgs/{org_id}/devices/radio_macs',
  tags: ['Orgs Devices'],
  summary: 'getOrgApsMacs',
  description: 'Get Org AP Device Mac and Radio MACs',
  operationId: 'getOrgApsMacs',
  request: { params: z.object({ org_id: OrgIdParamsSchema }) },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .object({ mac: z.string().min(1), radio_macs: z.array(z.object({})) })
                .openapi({ required: ['mac', 'radio_macs'] }),
            )
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            })
            .openapi({
              description: '',
              'x-examples': {
                'example-1': [
                  {
                    mac: '5c5b35000001',
                    radio_macs: ['5c5b35000040', '5c5b35000050', '5c5b35000060'],
                  },
                  {
                    mac: '5c5b45000001',
                    radio_macs: ['5c5b45000040', '5c5b45000050', '5c5b45000060'],
                  },
                ],
              },
            }),
          examples: {
            'example-1': {
              value: [
                {
                  mac: '5c5b35000001',
                  radio_macs: ['5c5b35000040', '5c5b35000050', '5c5b35000060'],
                },
                {
                  mac: '5c5b45000001',
                  radio_macs: ['5c5b45000040', '5c5b45000050', '5c5b45000060'],
                },
              ],
            },
          },
        },
      },
    },
  },
})

