export const postApiV1OrgsOrgIdInventoryReplaceRoute = createRoute({
  method: 'post',
  path: '/api/v1/orgs/{org_id}/inventory/replace',
  tags: ['Orgs Inventory'],
  summary: 'replaceOrgDevices',
  description:
    'It’s a common request we get from the customers. When a AP HW has problem and need a replacement, they would want to copy the existing attributes (Device Config) of this old AP to the new one. It can be done by providing the MAC of a device that’s currently in the inventory but not assigned. The Device replaced will become unassigned.\n\n**Note:** For Gateway devices only like-for-like replacements (can only replace a SRX320 with a SRX320 and not some otehr model) are allowed.',
  operationId: 'replaceOrgDevices',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      description: 'Request Body',
      content: {
        'application/json': {
          schema: z
            .object({
              discard: z
                .array(z.string())
                .exactOptional()
                .openapi({ description: 'attributes that you don’t want to copy' }),
              inventory_mac: z
                .string()
                .openapi({
                  description:
                    'mac of the inventory that will be replacing the old one. It has to be claimed and unassigned.',
                }),
              mac: z.string().openapi({ description: 'device mac' }),
              site_id: z
                .uuid()
                .openapi({ description: 'the site_id of the device to be replaced' }),
            })
            .openapi({ required: ['inventory_mac', 'mac', 'site_id'] }),
          examples: {
            'example-1': {
              value: {
                discard: [],
                inventory_mac: '5c5b35000301',
                mac: '5c5b35000101',
                site_id: '4ac1dcf4-9d8b-7211-65c4-057819f0862b',
              },
            },
          },
        },
      },
    },
  },
  responses: { 200: OrgInventoryChangesResponse },
})

