export const putApiV1OrgsOrgIdLicensesRoute = createRoute({
  method: 'put',
  path: '/api/v1/orgs/{org_id}/licenses',
  tags: ['Orgs Licenses'],
  summary: 'moveOrDeleteOrgLicenseToAnotherOrg',
  description:
    'Move, Undo Move or Delete Org License to Another Org\nIf the admin has admin privilege against the `org_id` and `dst_org_id`, he can move some of the licenses to another Org. Given that: \n1. the specified license is currently active \n2. there’s enough licenses left in the specified license (by subscription_id) \n3. there will still be enough entitled licenses for the type of license after the amendment',
  operationId: 'moveOrDeleteOrgLicenseToAnotherOrg',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      description: 'Request Body',
      content: {
        'application/json': {
          schema: z
            .object({
              amendment_id: z
                .uuid()
                .exactOptional()
                .openapi({ description: 'if `op`==`unamend`, the ID of the operation to cancel' }),
              dst_org_id: z
                .uuid()
                .exactOptional()
                .openapi({
                  description: 'if `op`==`amend`, the id of the org where the licence is moved',
                }),
              notes: z.string().exactOptional().openapi({ description: 'if `op`==`annotate`' }),
              op: z
                .enum(['amend', 'unamend', 'delete', 'annotate'])
                .openapi({ description: 'to move a license, use the `amend` operation' }),
              quantity: z
                .int()
                .exactOptional()
                .openapi({ description: 'if `op`==`amend`, the number of licences to mo' }),
              subscription_id: z
                .string()
                .exactOptional()
                .openapi({ description: 'if `op`==`amend`, the ID of the subscription to use' }),
            })
            .openapi({ required: ['op'] }),
          examples: {
            annotate: {
              value: { notes: 'customer notes', op: 'annotate', subscription_id: 'SUB-000144' },
            },
            delete: { value: { op: 'delete', subscription_id: 'SUB-0000144' } },
            move: {
              value: {
                dst_org_id: '3eff35f7-c218-894e-bca2-24e5325601cc',
                op: 'amend',
                quantity: 10,
                subscription_id: 'SUB-0000144',
              },
            },
            undo_move: {
              value: { amendment_id: '2b9116ab-cd1e-e897-6e08-31fccd88e792', op: 'unamend' },
            },
          },
        },
      },
    },
  },
  responses: { 200: OKResponse },
})

