export const postApiV1OrgsOrgIdMapsImportRoute = createRoute({
  method: 'post',
  path: '/api/v1/orgs/{org_id}/maps/import',
  tags: ['Orgs Maps'],
  summary: 'importOrgMaps',
  description:
    'Import data from files is a multipart POST which has an file, an optional json, and an optional csv, to create floorplan, assign matching inventory to specific site, place ap if name or mac matches\n\n# CSV File Format\n```csv\nVendor AP name,Mist AP Mac\nUS Office AP-2 - 5c:5b:35:00:00:02,5c5b35000002\n``` ',
  operationId: 'importOrgMaps',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      description: '',
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              auto_deviceprofile_assignment: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({
                  description: 'boolean, whether to auto assign device to deviceprofile by name',
                }),
              csv: z
                .file()
                .exactOptional()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'csv file for ap name mapping, optional',
                }),
              file: z.file().exactOptional().openapi({ type: 'string', format: 'binary' }),
              json: z
                .object({
                  import_all_floorpans: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .default(false)
                    .exactOptional(),
                  import_height: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .default(true)
                    .exactOptional(),
                  import_orientation: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .default(true)
                    .exactOptional(),
                  site_id: z.uuid(),
                  vendor_name: z.enum(['ekahau', 'ibwave']),
                })
                .exactOptional()
                .openapi({ required: ['vendor_name', 'site_id'] }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              aps: z
                .array(
                  z
                    .object({
                      action: z
                        .enum([
                          'placed',
                          'assigned-placed',
                          'named-placed',
                          'assigned-named-placed',
                          'ignored',
                        ])
                        .exactOptional(),
                      floorplan_id: z.string().min(1).exactOptional(),
                      height: z.number().exactOptional(),
                      mac: z.string().min(1),
                      map_id: z.string().min(1).exactOptional(),
                      orientation: z.number().exactOptional(),
                      reason: z.string().min(1).exactOptional(),
                    })
                    .openapi({ required: ['mac'] }),
                )
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
              floorplans: z
                .array(
                  z
                    .object({
                      action: z.enum(['imported', 'ignored']).exactOptional(),
                      id: z.string().min(1).exactOptional(),
                      map_id: z.string().min(1).exactOptional(),
                      name: z.string().min(1).exactOptional(),
                      reason: z.string().min(1).exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                })
                .exactOptional(),
              site_id: z.string().min(1),
              summary: z
                .object({
                  num_ap_assigned: z.number(),
                  num_inv_assigned: z.number().exactOptional(),
                  num_map_assigned: z.number().exactOptional(),
                })
                .exactOptional()
                .openapi({ required: ['num_ap_assigned'] }),
            })
            .openapi({
              description: '',
              required: ['site_id', 'aps'],
              'x-examples': {
                'example-1': {
                  aps: [
                    {
                      action: 'placed',
                      floorplan_id: 'cbdb7f0b-3be0-4872-88f9-58790b509c23-j68kows8',
                      height: 3,
                      mac: '5c5b35000001',
                      map_id: '845a23bf-bed9-e43c-4c86-6fa474be7ae5',
                      orientation: 45,
                      reason: 'not found on site',
                    },
                  ],
                  floorplans: [
                    {
                      action: 'ignored',
                      id: 'cbdb7f0b-3be0-4872-88f9-58790b509c23-j68kows8',
                      map_id: '845a23bf-bed9-e43c-4c86-6fa474be7ae5',
                      name: 'map1',
                      reason: 'no aps placed',
                    },
                  ],
                  site_id: '4ac1dcf4-9d8b-7211-65c4-057819f0862b',
                  summary: { num_ap_assigned: 1, num_inv_assigned: 1, num_map_assigned: 1 },
                },
              },
            }),
          examples: {
            'example-1': {
              value: {
                aps: [
                  {
                    action: 'ignored',
                    floorplan_id: 'cbdb7f0b-3be0-4872-88f9-58790b509c23-j68kows8',
                    height: 3,
                    mac: '5c5b35000001',
                    orientation: 45,
                  },
                  {
                    action: 'placed',
                    height: 3,
                    mac: '5c5b35000001',
                    map_id: '845a23bf-bed9-e43c-4c86-6fa474be7ae5',
                    orientation: 45,
                  },
                ],
                floorplans: [
                  {
                    action: 'ignored',
                    id: 'cbdb7f0b-3be0-4872-88f9-58790b509c23-j68kows8',
                    map_id: '845a23bf-bed9-e43c-4c86-6fa474be7ae5',
                    name: 'map1',
                    reason: 'no aps placed',
                  },
                ],
                site_id: '4ac1dcf4-9d8b-7211-65c4-057819f0862b',
                summary: { num_ap_assigned: 1, num_inv_assigned: 1, num_map_assigned: 1 },
              },
            },
          },
        },
      },
    },
  },
})

