  method: 'get',
  path: '/api/v1/orgs/{org_id}/mxedges/upgrade',
  tags: ['Orgs MxEdges'],
  summary: 'getOrgMxEdgeUpgrades',
  description: 'Get Mist Edge Upgrades',
