export const postApiV1OrgsOrgIdMxedgesUpgradeRoute = createRoute({
  method: 'post',
  path: '/api/v1/orgs/{org_id}/mxedges/upgrade',
  tags: ['Orgs MxEdges'],
  summary: 'upgradeOrgMxEdges',
  description: 'Upgrade Mist Edges',
  operationId: 'upgradeOrgMxEdges',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      description: 'Request Body',
      content: {
        'application/json': {
          schema: z
            .object({
              allow_downgrades: z
                .object({
                  mxagent: z.boolean().default(false).exactOptional(),
                  mxdas: z.boolean().default(false).exactOptional(),
                  mxocproxy: z.boolean().default(false).exactOptional(),
                  radsecproxy: z.boolean().default(false).exactOptional(),
                  tunterm: z.boolean().default(false).exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'whether downgrade is allowed when running version is higher than expected version for each service',
                  required: [],
                }),
              channel: z
                .enum(['stable', 'beta', 'alpha'])
                .default('stable')
                .exactOptional()
                .openapi({
                  description: 'upgrade channel to follow, stable (default) / beta / alpha',
                }),
              distro: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'distro upgrade, optional, to specific codename (e.g. bullseye) with highest qualified versions',
                }),
              mxedge_ids: z
                .array(z.uuid())
                .openapi({
                  description:
                    'list of mxedge IDs to upgrade. If not specified, it means all the org mxedges.',
                }),
              strategy: z
                .enum(['big_bang', 'serial'])
                .default('big_bang')
                .exactOptional()
                .openapi({
                  description: '* `big_bang`: upgrade all at once\n* `serial`: one at a time\n',
                }),
              versions: z
                .object({
                  mxagent: z.string(),
                  mxdas: z.string().exactOptional(),
                  mxocproxy: z.string().exactOptional(),
                  radsecproxy: z.string().exactOptional(),
                  tunterm: z.string(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'version to upgrade for each service, optional (ignored if distro upgrade)',
                  required: ['mxagent', 'tunterm'],
                }),
            })
            .openapi({ required: ['mxedge_ids'] }),
          examples: {
            'example-1': {
              value: {
                channel: 'stable',
                mxedge_ids: ['387804a7-3474-85ce-15a2-f9a9684c9c90'],
                versions: { mxagent: 'current', tunterm: 'default' },
              },
            },
          },
        },
      },
    },
  },
  responses: { 200: OKResponse },
})

