export const postApiV1OrgsOrgIdPsksImportRoute = createRoute({
  method: 'post',
  path: '/api/v1/orgs/{org_id}/psks/import',
  tags: ['Orgs Psks'],
  summary: 'importOrgPsks',
  description:
    'Import PSK from CSV file or JSON\n\n## CSV File Format\n```\nPSK Import CSV File Format:\nname,ssid,passphrase,usage,vlan_id,mac,max_usage,role,expire_time,notify_expiry,expiry_notification_time,notify_on_create_or_edit,email\nCommon,warehouse,foryoureyesonly,single,35,a31425f31278,0,student,1618594236\nJustin,reception,visible,multi,1002,200,teacher,1618594236\nCommon2,ssid,1245678-xx,single,35,a31425f31278,0,student,1618594236,true,7,true,admin@test.com\n```',
  operationId: 'importOrgPsks',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .array(PskSchema)
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            })
            .openapi({
              description: '',
              'x-examples': {
                'example-1': [
                  {
                    expire_time: '1618594236',
                    mac: 'a31425f31278',
                    max_usage: 300,
                    name: 'Common',
                    passphrase: 'foryoureyesonly',
                    role: 'teacher',
                    ssid: 'warehouse',
                    usage: 'single',
                    vlan_id: 35,
                  },
                  {
                    mac: null,
                    name: 'Justin',
                    passphrase: 'visible',
                    ssid: 'reception',
                    usage: 'multi',
                    vlan_id: 1002,
                  },
                ],
              },
            }),
          examples: {
            'example-1': {
              value: [
                {
                  created_time: 0,
                  expire_time: 1614990263,
                  id: '425f6eca-6376-4993-bfeb-53cbbbba6f06',
                  mac: 'string',
                  max_usage: 0,
                  modified_time: 0,
                  name: 'string',
                  org_id: 'a40f5d1f-d889-42e9-94ea-b9b33585fc6b',
                  passphrase: 'stringst',
                  site_id: '72771e6a-6f5e-4de4-a5b9-1266c4197811',
                  ssid: 'string',
                  usage: 'multi',
                  vlan_id: 0,
                },
              ],
            },
          },
        },
        'multipart/form-data': {
          schema: z
            .object({
              file: z.file().exactOptional().openapi({ type: 'string', format: 'binary' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: { 200: PsksArrayResponse },
})

