export const postApiV1OrgsOrgIdSettingJuniperLinkAccountsRoute = createRoute({
  method: 'post',
  path: '/api/v1/orgs/{org_id}/setting/juniper/link_accounts',
  tags: ['Orgs'],
  summary: 'linkOrgToJuniperJuniperAccount',
  description: 'Link Juniper Accounts',
  operationId: 'linkOrgToJuniperJuniperAccount',
  request: {
    params: z.object({
      org_id: z
        .uuid()
        .openapi({
          param: {
            in: 'path',
            name: 'org_id',
            required: true,
            schema: {
              example: '000000ab-00ab-00ab-00ab-0000000000ab',
              format: 'uuid',
              type: 'string',
            },
          },
          example: '000000ab-00ab-00ab-00ab-0000000000ab',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({ password: z.string().exactOptional(), username: z.string().exactOptional() })
            .openapi({
              'x-examples': { 'example-1': { password: 'password', username: 'john@nmo.com' } },
              required: [],
            }),
          examples: { 'example-1': { value: { password: 'string', username: 'string' } } },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'account linked',
      content: {
        'application/json': {
          schema: z
            .object({
              account: z
                .object({ linked_by: z.string().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({
              'x-examples': {
                'example-1': {
                  account: { linked_by: 'John Smith (john@abccorp.com)', name: 'ABC Corp' },
                },
              },
              required: [],
            }),
          examples: {
            'example-1': {
              value: { account: { linked_by: 'John Smith (john@abccorp.com)', name: 'ABC Corp' } },
            },
          },
        },
      },
    },
    400: {
      description: 'account already linked',
      content: {
        'application/json': {
          schema: z
            .object({ detail: z.string().exactOptional() })
            .openapi({
              'x-examples': { 'example-1': { detail: 'Account[ABC Corp] already linked' } },
              required: [],
            }),
          examples: { 'example-1': { value: { detail: 'Account[ABC Corp] already linked' } } },
        },
      },
    },
  },
})

