export const postApiV1OrgsOrgIdSsrUpgradeRoute = createRoute({
  method: 'post',
  path: '/api/v1/orgs/{org_id}/ssr/upgrade',
  tags: ['Orgs Devices SSR'],
  summary: 'upgradeOrgSsrs',
  description: 'Upgrade Org SSRs',
  operationId: 'upgradeOrgSsrs',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    body: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              channel: z
                .enum(['stable', 'beta', 'alpha'])
                .default('stable')
                .exactOptional()
                .openapi({ description: 'upgrade channel to follow' }),
              device_ids: z
                .array(z.uuid())
                .openapi({ description: 'list of 128T device IDs to upgrade' }),
              reboot_at: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'reboot start time in epoch seconds, default is start_time, -1 disables reboot',
                }),
              start_time: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    '128T firmware download start time in epoch seconds, default is now, -1 disables download',
                }),
              strategy: z
                .enum(['big_bang', 'serial'])
                .default('big_bang')
                .exactOptional()
                .openapi({
                  description: '* `big_bang`: upgrade all at once\n* `serial`: one at a time',
                }),
              version: z
                .string()
                .min(1)
                .exactOptional()
                .openapi({ description: '128T firmware version to upgrade (e.g. 5.3.0-93)' }),
            })
            .openapi({
              description: '',
              required: ['device_ids'],
              'x-examples': {
                'example-1': {
                  channel: 'stable',
                  device_ids: [
                    '00000000-0000-0000-1000-5c5b3500001f',
                    '00000000-0000-0000-1000-5c5b35000020',
                  ],
                  strategy: 'big_bang',
                  version: '5.3.0-93',
                },
              },
            }),
          examples: {
            'example-1': {
              value: {
                channel: 'stable',
                device_ids: [
                  '00000000-0000-0000-1000-5c5b3500001f',
                  '00000000-0000-0000-1000-5c5b35000020',
                ],
                strategy: 'big_bang',
                version: '5.3.0-93',
              },
            },
          },
        },
      },
    },
  },
  responses: { 200: SsrUpgradeResponse },
})

