export const getApiV1OrgsOrgIdSsrVersionsRoute = createRoute({
  method: 'get',
  path: '/api/v1/orgs/{org_id}/ssr/versions',
  tags: ['Orgs Devices'],
  summary: 'getOrgSsrUpgradeInfo',
  description: 'Get Org SSD Ugprade information',
  operationId: 'getOrgSsrUpgradeInfo',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    query: z.object({
      channel: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'channel', schema: { type: 'string' }, required: false },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .object({
                  _version: z.string().min(1),
                  default: z.boolean().exactOptional(),
                  package: z.string().min(1),
                  version: z.string().min(1),
                })
                .openapi({ required: ['package', 'version', '_version'] }),
            )
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            })
            .openapi({
              description: '',
              'x-examples': {
                'example-1': [
                  {
                    _version: '128T-5.3.1-17.el7.x86_64',
                    default: true,
                    package: '128T',
                    version: '5.3.1-17',
                  },
                  {
                    _version: '128T-wheeljack-0.1.0-1212.x86_64',
                    package: '128T-wheeljack',
                    version: '0.1.0-1212',
                  },
                ],
              },
            }),
          examples: {
            'example-1': {
              value: [
                {
                  _version: '128T-5.3.1-17.el7.x86_64',
                  default: true,
                  package: '128T',
                  version: '5.3.1-17',
                },
                {
                  _version: '128T-wheeljack-0.1.0-1212.x86_64',
                  package: '128T-wheeljack',
                  version: '0.1.0-1212',
                },
              ],
            },
          },
        },
      },
    },
  },
})

