export const getApiV1OrgsOrgIdWiredClientsSearchRoute = createRoute({
  method: 'get',
  path: '/api/v1/orgs/{org_id}/wired_clients/search',
  tags: ['Orgs Clients'],
  summary: 'searchOrgClientsWired',
  description:
    'Search for Wired Clients in org\n\nNote: For list of avaialable `type` values, please refer to [getClientEventsDefinitions](/#tag/Constants/operation/getClientEventsDefinitions)',
  operationId: 'searchOrgClientsWired',
  request: {
    params: z.object({ org_id: OrgIdParamsSchema }),
    query: z.object({
      site_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Site ID',
            in: 'query',
            name: 'site_id',
            schema: { type: 'string' },
            required: false,
          },
        }),
      device_mac: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'device mac',
            in: 'query',
            name: 'device_mac',
            schema: { type: 'string' },
            required: false,
          },
        }),
      mac: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'client mac',
            in: 'query',
            name: 'mac',
            schema: { type: 'string' },
            required: false,
          },
        }),
      port_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'port id',
            in: 'query',
            name: 'port_id',
            schema: { type: 'string' },
            required: false,
          },
        }),
      vlan: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'vlan',
            in: 'query',
            name: 'vlan',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      ip: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'ip',
            in: 'query',
            name: 'ip',
            schema: { type: 'string' },
            required: false,
          },
        }),
      manufacture: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'client manufacture',
            in: 'query',
            name: 'manufacture',
            schema: { type: 'string' },
            required: false,
          },
        }),
      text: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'single entry of hostname/mac',
            in: 'query',
            name: 'text',
            schema: { type: 'string' },
            required: false,
          },
        }),
      limit: LimitParamsSchema,
      start: StartParamsSchema,
      end: EndParamsSchema,
      duration: DurationParamsSchema,
    }),
  },
  responses: { 200: WiredClientsSearchResponse },
})

