export const postApiV1RegisterRoute = createRoute({
  method: 'post',
  path: '/api/v1/register',
  tags: ['Admin'],
  summary: 'registerNewAdmin',
  description:
    'Register a new admin and his/her org\nAn email will also be sent to the user with a link to https://manage.mist.com/verify/register?token=:token',
  operationId: 'registerNewAdmin',
  request: {
    body: {
      description: 'Request Body',
      content: {
        'application/json': {
          schema: z
            .object({
              account_only: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({ description: 'skip creating initial setup if true' }),
              allow_mist: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({ description: 'whether to allow Mist to look at this org' }),
              email: z.string(),
              first_name: z.string(),
              invite_code: z
                .string()
                .exactOptional()
                .openapi({ description: 'required initially' }),
              last_name: z.string(),
              org_name: z.string(),
              password: z.string(),
              recaptcha: z.string(),
              referer_invite_token: z
                .string()
                .exactOptional()
                .openapi({ description: 'the invite token to apply after account creation' }),
              return_to: z
                .string()
                .exactOptional()
                .openapi({ description: 'the url the user should be redirected back to' }),
            })
            .openapi({
              required: ['email', 'password', 'first_name', 'last_name', 'org_name', 'recaptcha'],
            }),
        },
      },
    },
  },
  responses: { 200: OKResponse },
})

export const postApiV1RegisterVerifyTokenRoute = createRoute({
  method: 'post',
  path: '/api/v1/register/verify/{token}',
  tags: ['Admin'],
  summary: 'verifyRegistration',
  description: 'Verify registration',
  operationId: 'verifyRegistration',
  request: { params: z.object({ token: TokenParamsSchema }) },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              detail: z.string().exactOptional(),
              invite_not_applied: z.boolean().exactOptional(),
              min_length: z.int().exactOptional(),
              return_to: z.string().exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            'Response if successful': {
              value: { return_to: 'http://mist.zendesk.com/hc/quickstart.pdf' },
            },
            'Response if successful but failed to apply the invitation automatically': {
              value: { detail: 'password policy not met', invite_not_applied: true, min_length: 8 },
            },
          },
        },
      },
      headers: z.object({
        'Set-Cookie': {
          schema: z
            .string()
            .exactOptional()
            .openapi({
              param: { required: false },
              example:
                'csrftoken=vwvBuq9qkqaKh7lu8tNc0gkvBfEaLAmx; expires=Tue, 15-Mar-2016 19:47:20 GMT; Max-Age=31449600; Path=/',
            }),
        },
      }),
    },
    400: {
      description: 'Response if verification expired or already registered',
      content: {
        'application/json': {
          schema: z.object({ detail: z.string() }).openapi({ required: ['detail'] }),
          examples: {
            'already registered': { value: { detail: 'already registered' } },
            'verification expired': { value: { detail: 'expired' } },
          },
        },
      },
    },
    404: {
      description: 'Response if secret is invalid',
      content: {
        'application/json': {
          schema: z.object({ detail: z.string() }).openapi({ required: ['detail'] }),
          examples: { 'example-1': { value: { detail: 'Not found.' } } },
        },
      },
    },
  },
})

