export const getApiV1SitesSiteIdAppsRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/apps',
  tags: ['Sites Applications'],
  summary: 'getSiteApps',
  description: 'Get Application List',
  operationId: 'getSiteApps',
  request: { params: z.object({ site_id: SiteIdParamsSchema }) },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .object({
                  group: z.string().min(1),
                  key: z.string().min(1),
                  name: z.string().min(1),
                })
                .openapi({ required: ['key', 'name', 'group'] }),
            )
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            })
            .openapi({
              description: '',
              'x-examples': {
                'example-1': [{ group: 'Emails', key: 'gmail', name: 'Gmail - web/app' }],
              },
            }),
          examples: {
            'example-1': { value: [{ group: 'string', key: 'string', name: 'string' }] },
          },
        },
      },
    },
  },
})

