export const postApiV1SitesSiteIdClientsDisconnectRoute = createRoute({
  method: 'post',
  path: '/api/v1/sites/{site_id}/clients/disconnect',
  tags: ['Sites Clients'],
  summary: 'disconnectSiteMultipleClients',
  description: 'To unauthorize multiple clients',
  operationId: 'disconnectSiteMultipleClients',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    body: {
      description: 'Request Body',
      content: {
        'application/json': {
          schema: z
            .array(z.string())
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
          examples: { 'example-1': { value: ['683b679ac024'] } },
        },
      },
    },
  },
  responses: { 200: OKResponse },
})

export const getApiV1SitesSiteIdClientsEventsCountRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/clients/events/count',
  tags: ['Sites Clients'],
  summary: 'countSiteByDistinctAttributesOfClientsEvents',
  description: 'Count by Distinct Attributes of Client-Events',
  operationId: 'countSiteByDistinctAttributesOfClientsEvents',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    query: z.object({
      distinct: z
        .enum(['type', 'proto', 'band', 'channel', 'wlan_id', 'ssid'])
        .exactOptional()
        .openapi({
          param: {
            description: 'type / proto / band / channel / wlan_id / ssid',
            example: 'type',
            in: 'query',
            name: 'distinct',
            schema: {
              enum: ['type', 'proto', 'band', 'channel', 'wlan_id', 'ssid'],
              type: 'string',
            },
            required: false,
          },
        }),
      type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'event type, e.g. MARVIS_EVENT_CLIENT_FBT_FAILURE',
            in: 'query',
            name: 'type',
            schema: { type: 'string' },
            required: false,
          },
        }),
      reason_code: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'for assoc/disassoc events',
            in: 'query',
            name: 'reason_code',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      ssid: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'SSID Name',
            in: 'query',
            name: 'ssid',
            schema: { type: 'string' },
            required: false,
          },
        }),
      ap: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'AP MAC',
            in: 'query',
            name: 'ap',
            schema: { type: 'string' },
            required: false,
          },
        }),
      proto: z
        .enum(['b', 'g', 'n', 'ac', 'ax', 'a'])
        .exactOptional()
        .openapi({
          param: {
            description: '802.11 standard',
            in: 'query',
            name: 'proto',
            schema: { enum: ['b', 'g', 'n', 'ac', 'ax', 'a'], type: 'string' },
            required: false,
          },
        }),
      band: z
        .enum(['24', '5'])
        .exactOptional()
        .openapi({
          param: {
            description: '24 / 5',
            in: 'query',
            name: 'band',
            schema: { enum: ['24', '5'], type: 'string' },
            required: false,
          },
        }),
      wlan_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'wlan_id',
            in: 'query',
            name: 'wlan_id',
            schema: { type: 'string' },
            required: false,
          },
        }),
      page: PageParamsSchema,
      limit: LimitParamsSchema,
      start: StartParamsSchema,
      end: EndParamsSchema,
      duration: DurationParamsSchema,
    }),
  },
  responses: { 200: CountResponse },
})

