export const postApiV1SitesSiteIdClientsUnauthorizeRoute = createRoute({
  method: 'post',
  path: '/api/v1/sites/{site_id}/clients/unauthorize',
  tags: ['Sites Clients'],
  summary: 'unauthorizeSiteMultipleClients',
  description:
    'This unauthorize clients (if they are guest) and disconnect them. From the guest’s perspective, they will see the splash page again and go through the flow (e.g. Terms of Use) again.',
  operationId: 'unauthorizeSiteMultipleClients',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    body: {
      description: 'Request Body',
      content: {
        'application/json': {
          schema: z
            .array(z.string())
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
          examples: { 'example-1': { value: ['683b679ac024'] } },
        },
      },
    },
  },
  responses: { 200: OKResponse },
})

