export const getApiV1SitesSiteIdDevicesDeviceIdConfigCmdRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/devices/{device_id}/config_cmd',
  tags: ['Sites Devices'],
  summary: 'getSiteDeviceConfigCmd',
  description:
    'Get Config CLI Commands\nFor a brown-field switch deployment where we adopted the switch through Adoption Command, we do not wipe out / overwrite the existing config automatically. Instead, we generate CLI commands that we would have generated. The user can inspect, modify, and incorporate this into their existing config manually.\n\nOnce they feel comfortable about the config we generate, they can enable allow_mist_config where we will take full control of their config like a claimed switch',
  operationId: 'getSiteDeviceConfigCmd',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema, device_id: DeviceIdParamsSchema }),
    query: z.object({
      sort: z
        .enum(['true', 'false'])
        .default('false')
        .exactOptional()
        .openapi({
          param: {
            description: 'Make output cmds sorted (for better readability) or not.',
            in: 'query',
            name: 'sort',
            schema: { default: 'false', enum: ['true', 'false'], type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: DeviceConfigCmdResponse },
})

