export const postApiV1SitesSiteIdDevicesDeviceIdImageImageNumberRoute = createRoute({
  method: 'post',
  path: '/api/v1/sites/{site_id}/devices/{device_id}/image{image_number}',
  tags: ['Sites Devices'],
  summary: 'addSiteDeviceImage',
  description: 'Attach up to 3 images to a device',
  operationId: 'addSiteDeviceImage',
  request: {
    params: z.object({
      site_id: SiteIdParamsSchema,
      device_id: DeviceIdParamsSchema,
      image_number: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: { in: 'path', name: 'image_number', required: true, schema: { type: 'integer' } },
        }),
    }),
    body: {
      description: 'Request Body',
      content: { 'multipart/form-data': { schema: ImageUploadSchema } },
    },
  },
  responses: { 200: OKResponse },
})

