export const postApiV1SitesSiteIdDevicesDeviceIdVcVcPortRoute = createRoute({
  method: 'post',
  path: '/api/v1/sites/{site_id}/devices/{device_id}/vc/vc_port',
  tags: ['Sites Devices Switches Virtual Chassis'],
  summary: 'setSiteVcPort',
  description: 'Set VC port',
  operationId: 'setSiteVcPort',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema, device_id: DeviceIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              members: z
                .array(
                  z
                    .object({ member: z.number(), vc_ports: z.array(z.string()).exactOptional() })
                    .openapi({ required: ['member'] }),
                )
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
              op: z.enum(['set', 'delete']),
            })
            .openapi({
              description: '',
              required: ['op', 'members'],
              'x-examples': {
                'example-1': {
                  members: [
                    { member: 0, vc_ports: ['xe-0/1/1'] },
                    { member: 2, vc_ports: ['xe-0/1/1'] },
                  ],
                  op: 'set',
                },
              },
            }),
          examples: {
            'Delete VC port of xe-0/1/1 of member 0 and member 2': {
              value: {
                members: [
                  { member: 0, vc_ports: ['xe-0/1/1'] },
                  { member: 2, vc_ports: ['xe-0/1/1'] },
                ],
                op: 'delete',
              },
            },
            'Set VC port of xe-0/1/1 of member 0 and member 2': {
              value: {
                members: [
                  { member: 0, vc_ports: ['xe-0/1/1'] },
                  { member: 2, vc_ports: ['xe-0/1/1'] },
                ],
                op: 'set',
              },
            },
          },
        },
      },
    },
  },
  responses: { 200: OKResponse },
})

