export const postApiV1SitesSiteIdMapsMapIdAutoPlacementRoute = createRoute({
  method: 'post',
  path: '/api/v1/sites/{site_id}/maps/{map_id}/auto_placement',
  tags: ['Sites Maps'],
  summary: 'runSiteApAutoplacement',
  description:
    'This API is called to trigger a map for auto placement. For auto placement feature to work, RTT-FTM data need to be collected from the APs on the map. This scan is disruptive and therefore the user must be notified of service disrution during the functioning of auto placement Repeated POST to this endpoint while a map is still running will be rejected.\n\nList of devices to provide suggestions for is an optional parameter that can be given to this API. This will provide autoplacement suggestions only for the devices specified. If no list of devices is provided, all APs asociated with that map are considered by default',
  operationId: 'runSiteApAutoplacement',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema, map_id: MapIdParamsSchema }),
    body: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              device_ids: z
                .array(z.string())
                .exactOptional()
                .openapi({ description: 'list of device macs' }),
              force_collection: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    '* If `force_collection`==`false`: the API Iattempts to start localization with existing data. \n* If `force_collection`==`true`: maintenance the API attempts to start orchestration.',
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: { description: 'Autoplacement Process has begun for this map' },
    400: {
      description:
        '* Map has less than 3 APs associated with it to perform auto placement \n* Insufficient anchors for auto placement. 3 required\n* Auto AP Placement is already in progress for this Map\n* Autoplacement data does not exist or has gone stale',
    },
  },
})

