export const postApiV1SitesSiteIdMapsMapIdReplaceRoute = createRoute({
  method: 'post',
  path: '/api/v1/sites/{site_id}/maps/{map_id}/replace',
  tags: ['Sites Maps'],
  summary: 'replaceSiteMapImage',
  description:
    'Replace Map Image\n\n\nThis works like an PUT where the image will be replaced. If transform is provided, all the locations of the objects on the map (AP, Zone, Vbeacon, Beacon) will be transformed as well (relative to the new Map)',
  operationId: 'replaceSiteMapImage',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema, map_id: MapIdParamsSchema }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              file: z.file().min(1).openapi({ type: 'string', format: 'binary' }),
              json: z
                .object({
                  transform: z
                    .object({
                      rotate: z
                        .preprocess(
                          (val) =>
                            typeof val === 'string' &&
                            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                              ? Number(val)
                              : val,
                          z.number(),
                        )
                        .exactOptional(),
                      scale: z
                        .preprocess(
                          (val) =>
                            typeof val === 'string' &&
                            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                              ? Number(val)
                              : val,
                          z.number(),
                        )
                        .exactOptional(),
                      x: z
                        .preprocess(
                          (val) =>
                            typeof val === 'string' &&
                            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                              ? Number(val)
                              : val,
                          z.number(),
                        )
                        .exactOptional(),
                      y: z
                        .preprocess(
                          (val) =>
                            typeof val === 'string' &&
                            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                              ? Number(val)
                              : val,
                          z.number(),
                        )
                        .exactOptional(),
                    })
                    .exactOptional()
                    .openapi({
                      description:
                        'If `transform` is provided, all the locations of the objects on the map (AP, Zone, Vbeacon, Beacon) will be transformed as well (relative to the new Map)',
                      required: [],
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({
              description: '',
              required: ['file'],
              'x-examples': {
                'example-1': {
                  file: 'rez',
                  json: { transform: { rotate: 0, scale: 1, x: 200, y: 150 } },
                },
              },
            }),
          examples: {
            'example-1': {
              value: { file: 'string', json: { transform: { rotate: 0, scale: 0, x: 0, y: 0 } } },
            },
          },
        },
      },
    },
  },
  responses: { 200: OKResponse },
})

