export const getApiV1SitesSiteIdRoguesEventsSearchRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/rogues/events/search',
  tags: ['Sites Rogues'],
  summary: 'searchSiteRogueEvents',
  description: 'Search Rogue Events',
  operationId: 'searchSiteRogueEvents',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    query: z.object({
      type: RogueTypeParamsSchema,
      ssid: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'ssid of the network detected as threat',
            in: 'query',
            name: 'ssid',
            schema: { type: 'string' },
            required: false,
          },
        }),
      bssid: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'bssid of the network detected as threat',
            in: 'query',
            name: 'bssid',
            schema: { type: 'string' },
            required: false,
          },
        }),
      ap_mac: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'mac of the device that had strongest signal strength for ssid/bssid pair',
            in: 'query',
            name: 'ap_mac',
            schema: { type: 'string' },
            required: false,
          },
        }),
      channel: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'channel over which ap_mac heard ssid/bssid pair',
            in: 'query',
            name: 'channel',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      seen_on_lan: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'whether the reporting AP see a wireless client (on LAN) connecting to it  ',
            in: 'query',
            name: 'seen_on_lan',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      limit: LimitParamsSchema,
      start: StartParamsSchema,
      end: EndParamsSchema,
      duration: DurationParamsSchema,
    }),
  },
  responses: { 200: RogueEventsSearchResponse },
})

