export const getApiV1SitesSiteIdSkyatpEventsCountRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/skyatp/events/count',
  tags: ['Sites Skyatp'],
  summary: 'countSiteByDistringAttributesOfSkyatpEvents',
  description: 'Count by Distinct Attributes of Skyatp Events (WIP)',
  operationId: 'countSiteByDistringAttributesOfSkyatpEvents',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    query: z.object({
      distinct: z
        .enum(['type', 'mac', 'device_mac', 'threat_level'])
        .default('type')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'distinct',
            schema: {
              default: 'type',
              enum: ['type', 'mac', 'device_mac', 'threat_level'],
              type: 'string',
            },
            required: false,
          },
        }),
      type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'event type, e.g. cc, fs, mw',
            in: 'query',
            name: 'type',
            schema: { type: 'string' },
            required: false,
          },
        }),
      mac: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'client MAC',
            in: 'query',
            name: 'mac',
            schema: { type: 'string' },
            required: false,
          },
        }),
      device_mac: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'device MAC',
            in: 'query',
            name: 'device_mac',
            schema: { type: 'string' },
            required: false,
          },
        }),
      threat_level: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'threat level',
            in: 'query',
            name: 'threat_level',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      'ip address': IpParamsSchema,
      page: PageParamsSchema,
      limit: LimitParamsSchema,
      start: StartParamsSchema,
      end: EndParamsSchema,
      duration: DurationParamsSchema,
    }),
  },
  responses: { 200: CountResponse },
})

export const getApiV1SitesSiteIdSkyatpEventsSearchRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/skyatp/events/search',
  tags: ['Sites Skyatp'],
  summary: 'searchSiteSkyatpEvents',
  description: 'Search Skyatp Events (WIP)',
  operationId: 'searchSiteSkyatpEvents',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    query: z.object({
      type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'event type, e.g. cc, fs, mw',
            in: 'query',
            name: 'type',
            schema: { type: 'string' },
            required: false,
          },
        }),
      mac: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'client MAC',
            in: 'query',
            name: 'mac',
            schema: { type: 'string' },
            required: false,
          },
        }),
      device_mac: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'device MAC',
            in: 'query',
            name: 'device_mac',
            schema: { type: 'string' },
            required: false,
          },
        }),
      threat_level: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'threat level',
            in: 'query',
            name: 'threat_level',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      'ip address': IpParamsSchema,
      limit: LimitParamsSchema,
      start: StartParamsSchema,
      end: EndParamsSchema,
      duration: DurationParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              end: z.int(),
              limit: z.int(),
              next: z.string().exactOptional(),
              results: z
                .array(EventsSkyatpSchema)
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
              start: z.int(),
              total: z.int(),
            })
            .openapi({ required: ['end', 'limit', 'results', 'start', 'total'] }),
          examples: {
            'example-1': {
              value: {
                end: 1513176951,
                limit: 10,
                results: [
                  {
                    device_mac: '658279bb1fa4',
                    ip: '172.16.0.11',
                    mac: 'b019c66c8348',
                    org_id: '3139f2c2-fac6-11e5-8156-0242ac110006',
                    site_id: '70e0f468-fc13-11e5-85ad-0242ac110008',
                    threat_level: 7,
                    timestamp: 1592524478,
                    type: 'cc',
                  },
                ],
                start: 1512572151,
                total: 1,
              },
            },
          },
        },
      },
    },
  },
})

