export const getApiV1SitesSiteIdStatsAssetsSearchRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/stats/assets/search',
  tags: ['Sites Assets'],
  summary: 'searchSiteAssets',
  description: 'Assets Search',
  operationId: 'searchSiteAssets',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    query: z.object({
      mac: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'mac', schema: { type: 'string' }, required: false },
        }),
      map_id: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'map_id',
            schema: { format: 'uuid', type: 'string' },
            required: false,
          },
        }),
      ibeacon_uuid: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ibeacon_uuid',
            schema: { format: 'uuid', type: 'string' },
            required: false,
          },
        }),
      ibeacon_major: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ibeacon_major',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      ibeacon_minor: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'ibeacon_minor',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      eddystone_uid_namespace: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'eddystone_uid_namespace',
            schema: { type: 'string' },
            required: false,
          },
        }),
      eddystone_uid_instance: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'eddystone_uid_instance',
            schema: { type: 'string' },
            required: false,
          },
        }),
      eddystone_url: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'eddystone_url',
            schema: { type: 'string' },
            required: false,
          },
        }),
      device_name: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'device_name', schema: { type: 'string' }, required: false },
        }),
      by: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'by', schema: { type: 'string' }, required: false },
        }),
      name: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'name', schema: { type: 'string' }, required: false },
        }),
      ap_mac: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'ap_mac', schema: { type: 'string' }, required: false },
        }),
      beam: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'beam', schema: { type: 'string' }, required: false },
        }),
      rssi: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'rssi', schema: { type: 'string' }, required: false },
        }),
      limit: LimitParamsSchema,
      start: StartParamsSchema,
      end: EndParamsSchema,
      duration: DurationParamsSchema,
    }),
  },
  responses: { 200: AssetsArrayStatsSearchResponse },
})

