export const getApiV1SitesSiteIdStatsDiscoveredSwitchesCountRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/stats/discovered_switches/count',
  tags: ['Sites Stats'],
  summary: 'countSiteDiscoveredSwitches',
  description: 'Count Discovered Switches',
  operationId: 'countSiteDiscoveredSwitches',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    query: z.object({
      distinct: z
        .enum(['system_name', 'version', 'model', 'mgmt_addr'])
        .default('system_name')
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'distinct',
            schema: {
              default: 'system_name',
              enum: ['system_name', 'version', 'model', 'mgmt_addr'],
              type: 'string',
            },
            required: false,
          },
        }),
      page: PageParamsSchema,
      limit: LimitParamsSchema,
      start: StartParamsSchema,
      end: EndParamsSchema,
      duration: DurationParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              distinct: z.string(),
              end: z.number(),
              limit: z.int(),
              percentage: z.int(),
              results: z
                .array(
                  z
                    .object({ count: z.int(), system_name: z.string() })
                    .openapi({ required: ['system_name', 'count'] }),
                )
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
              start: z.number(),
              total: z.int(),
            })
            .openapi({
              required: ['results', 'start', 'end', 'limit', 'distinct', 'total', 'percentage'],
            }),
          examples: {
            'example-1': {
              value: {
                distinct: 'system_name',
                end: 1604496202.3555834,
                limit: 1000,
                percentage: 100,
                results: [
                  { count: 1, system_name: 'test-ex' },
                  { count: 1, system_name: 'sw-jn-01' },
                ],
                start: 1604409802.3555677,
                total: 2,
              },
            },
          },
        },
      },
    },
  },
})

export const getApiV1SitesSiteIdStatsDiscoveredSwitchesMetricsRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/stats/discovered_switches/metrics',
  tags: ['Sites Stats'],
  summary: 'getSiteDiscoveredSwitchesMetrics',
  description:
    'Discovered switches related metrics, lists related switch system names & details if not compliant',
  operationId: 'getSiteDiscoveredSwitchesMetrics',
  request: {
    params: z.object({ site_id: SiteIdParamsSchema }),
    query: z.object({
      threshold: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'configurable # ap per switch threshold, default 12',
            in: 'query',
            name: 'threshold',
            schema: { type: 'string' },
            required: false,
          },
        }),
      system_name: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'system name for switch level metrics, optional',
            in: 'query',
            name: 'system_name',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              inactive_wired_vlans: z
                .object({ details: z.object({}), score: z.number() })
                .openapi({ required: ['score', 'details'] }),
              poe_compliance: z
                .object({
                  details: z
                    .object({ total_aps: z.int(), total_power: z.number() })
                    .openapi({ required: ['total_power', 'total_aps'] }),
                  score: z.number(),
                })
                .openapi({ required: ['score', 'details'] }),
              switch_ap_affinity: z
                .object({
                  details: z
                    .object({ system_name: z.array(z.string()), threshold: z.number() })
                    .openapi({ required: ['threshold', 'system_name'] }),
                  score: z.number(),
                })
                .openapi({ required: ['score', 'details'] }),
              version_compliance: z
                .object({
                  details: z
                    .object({
                      major_versions: z
                        .array(
                          z
                            .object({
                              major_count: z.number(),
                              model: z.string(),
                              system_names: z.array(z.string()).exactOptional(),
                            })
                            .openapi({ required: ['model', 'major_count'] }),
                        )
                        .min(1)
                        .superRefine((items, ctx) => {
                          const seen = new Map()
                          for (const [i, val] of items.entries()) {
                            const key = JSON.stringify(val)
                            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                            else seen.set(key, i)
                          }
                        }),
                      total_switch_count: z.int(),
                    })
                    .openapi({ required: ['major_versions', 'total_switch_count'] }),
                  score: z.number(),
                })
                .openapi({ required: ['score', 'details'] }),
            })
            .openapi({
              required: [
                'version_compliance',
                'switch_ap_affinity',
                'inactive_wired_vlans',
                'poe_compliance',
              ],
            }),
          examples: {
            'example-1': {
              value: {
                inactive_wired_vlans: { details: {}, score: 100 },
                poe_compliance: { details: { total_aps: 63, total_power: 981500 }, score: 100 },
                switch_ap_affinity: {
                  details: { system_name: ['mist-lab-ex2300c', 'switch1'], threshold: 12 },
                  score: 33.3333,
                },
                version_compliance: {
                  details: {
                    major_versions: [
                      {
                        major_count: 2,
                        model: 'EX2300-C-12P',
                        system_names: ['switch1', 'mist-lab-ex2300c'],
                      },
                      { major_count: 1, model: 'EX4300-48P', system_names: [] },
                    ],
                    total_switch_count: 5,
                  },
                  score: 75,
                },
              },
            },
          },
        },
      },
    },
  },
})

