export const getApiV1SitesSiteIdWxtagsAppsRoute = createRoute({
  method: 'get',
  path: '/api/v1/sites/{site_id}/wxtags/apps',
  tags: ['Sites WxTags'],
  summary: 'getSiteApplicationList',
  description: 'Get Application List',
  operationId: 'getSiteApplicationList',
  request: { params: z.object({ site_id: SiteIdParamsSchema }) },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .object({ group: z.string(), key: z.string(), name: z.string() })
                .openapi({ required: ['key', 'name', 'group'] }),
            )
            .min(1)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
          examples: {
            'example-1': { value: [{ group: 'Emails', key: 'gmail', name: 'Gmail - web/app' }] },
          },
        },
      },
    },
  },
})

